    promoAnnouncementBody: 'プロジェクトには最強の起業家ベースが必要です。実際の TON 支払いを伴う 1 週間の大規模スプリントを開催します!\n\nマップには <b>478</b> の区画しかなく、最高の場所は今すぐ埋まっています。名を上げて、招待で稼ぐ時です!\n\n💰 <b>参加者全員の条件:</b>\nアクティブな紹介 1 人につき(マップ上のビジネスを購入)、<b>{per_active} TON</b> が残高に直接入金されます!キャンペーン終了後すぐに引き出し可能です。\n\n🏆 <b>トップ紹介者のメイン賞金プール:</b>\n最も多くのアクティブ参加者を招待した 3 人のリーダーが追加の賞金を分け合います:\n🥇 1 位 — <b>{p1} TON</b>\n🥈 2 位 — <b>{p2} TON</b>\n🥉 3 位 — <b>{p3} TON</b>\n\n⏱ <b>期間:</b>\nキャンペーンは今すぐ開始!最終集計と全報酬(TOP-3 を含む)の支払いは <b>{ends_at_en}</b> に行われます。\n\n📈 リーダーボードはゲーム内でリアルタイム更新 — 競争相手を監視し、最後の瞬間に追い越されないように!',
