// Transaction statuses (raw status key -> localized label)
export const transactionStatusI18n = {
  pending: { en: 'Pending', ru: 'В ожидании', es: 'Pendiente', zh: '等待中', fr: 'En attente', de: 'Ausstehend', ja: '保留中', ko: '대기 중' },
  processing: { en: 'Processing', ru: 'Обрабатывается', es: 'Procesando', zh: '处理中', fr: 'En traitement', de: 'In Bearbeitung', ja: '処理中', ko: '처리 중' },
  completed: { en: 'Completed', ru: 'Выполнено', es: 'Completado', zh: '已完成', fr: 'Terminé', de: 'Abgeschlossen', ja: '完了', ko: '완료' },
  approved: { en: 'Approved', ru: 'Одобрено', es: 'Aprobado', zh: '已批准', fr: 'Approuvé', de: 'Genehmigt', ja: '承認', ko: '승인됨' },
  failed: { en: 'Failed', ru: 'Ошибка', es: 'Error', zh: '失败', fr: 'Échoué', de: 'Fehler', ja: '失敗', ko: '실패' },
  rejected: { en: 'Rejected', ru: 'Отклонено', es: 'Rechazado', zh: '已拒绝', fr: 'Rejeté', de: 'Abgelehnt', ja: '却下', ko: '거절됨' },
};

export const tTransactionStatus = (status, lang = 'en') => {
  if (!status) return '';
  return transactionStatusI18n[status]?.[lang] || transactionStatusI18n[status]?.en || status;
};

export const tTransactionType = (type, lang = 'en') => {
  if (!type) return transactionTypeI18n.unknown[lang] || transactionTypeI18n.unknown.en;
  return transactionTypeI18n[type]?.[lang] || transactionTypeI18n[type]?.en || type;
};

